import { useId } from "react"
import { EllipsisIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"

import { IndeterminateCheckbox } from "./indeterminate-checkbox"
import { CHECKBOX_COLUMN, type BulkSelectAction } from "./types"
import type { SelectionState } from "./selection"

function BarButton({
  action,
  run,
}: {
  action: BulkSelectAction
  run: () => void
}) {
  const reasonId = useId()
  const reason = action.disabledReason
  const button = (
    <Button
      size="sm"
      variant="outline"
      aria-disabled={reason ? true : undefined}
      aria-describedby={reason ? reasonId : undefined}
      className="aria-disabled:cursor-not-allowed aria-disabled:opacity-50"
      onClick={() => {
        if (!reason) run()
      }}
    >
      {action.icon}
      {action.label}
    </Button>
  )
  if (!reason) return button
  return (
    <>
      <Tooltip>
        <TooltipTrigger asChild>{button}</TooltipTrigger>
        <TooltipContent>{reason}</TooltipContent>
      </Tooltip>
      <span id={reasonId} className="sr-only">
        {reason}
      </span>
    </>
  )
}

/**
 * The header band while rows are selected: the select-all box, the caller's
 * actions as buttons, an overflow menu for actions marked `overflow`, and the
 * count. A disabled action stays in place and gives its reason as a tooltip
 * (or a sub-line in the menu). Same height as the column header it replaces.
 */
export function ActionBar({
  actions,
  selectedIds,
  selectionState,
  noun,
  onToggleAll,
}: {
  actions: BulkSelectAction[]
  selectedIds: string[]
  selectionState: SelectionState
  noun: string
  onToggleAll: () => void
}) {
  const buttons = actions.filter((action) => !action.overflow)
  const menu = actions.filter((action) => action.overflow)
  const count = selectedIds.length
  return (
    <div
      role="toolbar"
      aria-label="Actions for the selected rows"
      className="flex h-10 items-center"
    >
      <div
        className="flex shrink-0 justify-center"
        style={{ width: CHECKBOX_COLUMN }}
      >
        <IndeterminateCheckbox
          checked={
            selectionState === "all"
              ? true
              : selectionState === "some"
                ? "mixed"
                : false
          }
          onToggle={onToggleAll}
          label="Select all rows"
        />
      </div>
      <div className="flex min-w-0 flex-wrap items-center gap-1.5 pr-3">
        {buttons.map((action) => (
          <BarButton
            key={action.id}
            action={action}
            run={() => action.onSelect(selectedIds)}
          />
        ))}
        {menu.length > 0 ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                size="icon-sm"
                variant="outline"
                aria-label="More actions"
              >
                <EllipsisIcon aria-hidden />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start" className="min-w-52">
              {menu.map((action) => (
                <DropdownMenuItem
                  key={action.id}
                  disabled={Boolean(action.disabledReason)}
                  onSelect={() => action.onSelect(selectedIds)}
                >
                  {action.icon}
                  <span className="flex flex-col">
                    <span>{action.label}</span>
                    {action.disabledReason ? (
                      <span className="text-xs text-muted-foreground">
                        {action.disabledReason}
                      </span>
                    ) : null}
                  </span>
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : null}
        <span className="ml-2 text-xs whitespace-nowrap text-muted-foreground tabular-nums">
          {count} {count === 1 ? noun : `${noun}s`} selected
        </span>
      </div>
    </div>
  )
}

import { useMemo, useRef, useState } from "react"
import { ChevronDownIcon, UserIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

import {
  filterAssigneeGroups,
  findAssignee,
  initials,
  type AssigneeGroup,
} from "./assignees"

function Avatar({ name }: { name?: string }) {
  if (!name) {
    return (
      <span className="flex size-6 shrink-0 items-center justify-center rounded-full border border-dashed border-muted-foreground/60 text-muted-foreground">
        <UserIcon className="size-3.5" aria-hidden />
      </span>
    )
  }
  return (
    <span
      aria-hidden
      className="flex size-6 shrink-0 items-center justify-center rounded-full bg-[var(--mini-accent-soft)] text-[10px] font-medium text-foreground"
    >
      {initials(name)}
    </span>
  )
}

/**
 * Avatar button that opens a popover to pick an assignee: a header with a
 * Clear link, an auto-focused search box, and the caller's groups. Choosing an
 * option or Clear calls `onChange` (with `null` for Clear) and closes it; Esc
 * closes it without changing anything.
 */
export function AssigneeCell({
  value,
  groups,
  onChange,
  label = "Assignee",
}: {
  value: string | null
  groups: AssigneeGroup[]
  onChange: (id: string | null) => void
  label?: string
}) {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState("")
  const searchRef = useRef<HTMLInputElement>(null)
  const current = findAssignee(groups, value)
  const shown = useMemo(
    () => filterAssigneeGroups(groups, query),
    [groups, query]
  )
  const name = current ? current.name : "unassigned"

  const choose = (id: string | null) => {
    onChange(id)
    setOpen(false)
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        if (!next) setQuery("")
      }}
    >
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`${label}: ${name}. Change`}
          title={current ? `${label}: ${current.name}` : `${label}: unassigned`}
          className="flex items-center gap-0.5 rounded-full border border-border bg-background p-0.5 pr-1.5 outline-none hover:bg-muted focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 aria-expanded:bg-muted"
        >
          <Avatar name={current?.name} />
          <ChevronDownIcon
            className="size-3 text-muted-foreground"
            aria-hidden
          />
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="end"
        className="w-64 gap-0 p-0"
        onOpenAutoFocus={(event) => {
          event.preventDefault()
          searchRef.current?.focus()
        }}
      >
        <div className="flex items-center justify-between px-3 pt-2.5 pb-1">
          <span className="text-xs font-medium">{label}</span>
          <Button
            variant="link"
            size="xs"
            disabled={value === null}
            onClick={() => choose(null)}
            className="h-auto p-0 text-xs"
          >
            Clear
          </Button>
        </div>
        <Command
          shouldFilter={false}
          className="rounded-none! bg-transparent p-0"
        >
          <CommandInput
            ref={searchRef}
            value={query}
            onValueChange={setQuery}
            placeholder="Search people or teams"
            aria-label={`Search ${label.toLowerCase()}`}
          />
          <CommandList>
            <CommandEmpty>No one matches.</CommandEmpty>
            {shown.map((group) => (
              <CommandGroup key={group.id} heading={group.label}>
                {group.options.map((option) => (
                  <CommandItem
                    key={option.id}
                    value={`${group.id}:${option.id}`}
                    data-checked={option.id === value}
                    onSelect={() => choose(option.id)}
                  >
                    <Avatar name={option.name} />
                    <span className="truncate">{option.name}</span>
                    {option.hint ? (
                      <span className="truncate text-xs text-muted-foreground">
                        {option.hint}
                      </span>
                    ) : null}
                  </CommandItem>
                ))}
              </CommandGroup>
            ))}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  )
}

export type AssigneeOption = { id: string; name: string; hint?: string }
export type AssigneeGroup = {
  id: string
  label: string
  options: AssigneeOption[]
}

/** Groups keeping only options whose name or hint contains `query`; groups left empty are dropped. */
export function filterAssigneeGroups(
  groups: AssigneeGroup[],
  query: string
): AssigneeGroup[] {
  const needle = query.trim().toLowerCase()
  if (!needle) return groups
  return groups
    .map((group) => ({
      ...group,
      options: group.options.filter((option) =>
        `${option.name} ${option.hint ?? ""}`.toLowerCase().includes(needle)
      ),
    }))
    .filter((group) => group.options.length > 0)
}

export function findAssignee(
  groups: AssigneeGroup[],
  id: string | null
): AssigneeOption | undefined {
  if (id === null) return undefined
  for (const group of groups) {
    const found = group.options.find((option) => option.id === id)
    if (found) return found
  }
  return undefined
}

/** Up to two capital letters from the first and last words of a name. */
export function initials(name: string): string {
  const words = name
    .replace(/[^\p{L}\p{N}\s]/gu, "")
    .split(/\s+/)
    .filter(Boolean)
  if (words.length === 0) return "?"
  const first = words[0][0]
  const last = words.length > 1 ? words[words.length - 1][0] : ""
  return `${first}${last}`.toUpperCase()
}

import {
  useEffect,
  useEffectEvent,
  useId,
  useMemo,
  useRef,
  useState,
  type MouseEvent as ReactMouseEvent,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Skeleton } from "@/components/ui/skeleton"
import { cn } from "@/lib/utils"

import { ActionBar } from "./action-bar"
import { IndeterminateCheckbox } from "./indeterminate-checkbox"
import {
  neighbourAfterRemoval,
  nextHighlight,
  pruneSelection,
  selectionState,
  setRange,
  toggleId,
} from "./selection"
import {
  CHECKBOX_COLUMN,
  type BulkSelectAction,
  type BulkSelectColumn,
  type BulkSelectRow,
} from "./types"

export type BulkSelectProps<T extends BulkSelectRow> = {
  items: T[]
  columns: BulkSelectColumn<T>[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  actions?: BulkSelectAction[]
  selectedIds?: string[]
  onSelectedIdsChange?: (ids: string[]) => void
  highlightedId?: string | null
  onHighlightedIdChange?: (id: string | null) => void
  onOpen?: (item: T) => void
  rowHeight?: number
  minWidth?: string
  rowLabel?: (item: T) => string
  selectionNoun?: string
  emptyTitle?: string
  emptyDescription?: string
  emptyAction?: { label: string; onClick: () => void }
  "aria-label"?: string
}

const PLACEHOLDER_ROWS = 6

const INTERACTIVE =
  "a,button,input,select,textarea,summary,[role=button],[role=link],[role=checkbox],[contenteditable=true]"

/** State that follows `value` when the parent passes one and is held locally otherwise. */
function useControllable<T>(
  value: T | undefined,
  initial: T,
  onChange?: (next: T) => void
): [T, (next: T) => void] {
  const [inner, setInner] = useState(initial)
  const controlled = value !== undefined
  const set = (next: T) => {
    if (!controlled) setInner(next)
    onChange?.(next)
  }
  return [controlled ? value : inner, set]
}

/**
 * Dense table of multi-line rows with a keyboard highlight and row selection.
 * While any row is selected the column header becomes an action bar in place.
 * The selection is exposed through `selectedIds` / `onSelectedIdsChange` so a
 * host can hand it to another pattern. Takes data as props and never reads the
 * store. Keys act when focus is on the page body or inside this block, never
 * while typing in an input. Columns, actions and cells are the caller's.
 */
export function BulkSelect<T extends BulkSelectRow>({
  items,
  columns,
  status = "ready",
  error,
  onRetry,
  actions = [],
  selectedIds: selectedProp,
  onSelectedIdsChange,
  highlightedId: highlightedProp,
  onHighlightedIdChange,
  onOpen,
  rowHeight = 84,
  minWidth = "44rem",
  rowLabel,
  selectionNoun = "row",
  emptyTitle = "Nothing here yet",
  emptyDescription,
  emptyAction,
  "aria-label": ariaLabel = "Table",
}: BulkSelectProps<T>) {
  const uid = useId()
  const rootRef = useRef<HTMLDivElement>(null)
  const gridRef = useRef<HTMLDivElement>(null)
  const anchorRef = useRef<string | null>(null)
  const previousOrder = useRef<string[]>([])

  const [selectedIds, setSelectedIds] = useControllable<string[]>(
    selectedProp,
    [],
    onSelectedIdsChange
  )
  const [highlightedId, setHighlightedId] = useControllable<string | null>(
    highlightedProp,
    null,
    onHighlightedIdChange
  )

  const ready = status === "ready"
  const order = useMemo(() => items.map((item) => item.id), [items])
  const selected = useMemo(
    () => pruneSelection(order, selectedIds),
    [order, selectedIds]
  )
  const chosen = useMemo(() => new Set(selected), [selected])
  const state = selectionState(selected.length, order.length)
  const showBar = ready && selected.length > 0
  const keysOn = ready && items.length > 0
  const highlightedItem = items.find((item) => item.id === highlightedId)

  const rowDomId = (id: string) => `${uid}-row-${encodeURIComponent(id)}`
  const focusGrid = () => gridRef.current?.focus({ preventScroll: true })
  const template = `${CHECKBOX_COLUMN} ${columns
    .map((column) => column.width ?? "minmax(0, 1fr)")
    .join(" ")}`

  const toggleRow = (id: string, shift: boolean) => {
    const anchor = anchorRef.current
    const next =
      shift && anchor !== null && anchor !== id && order.includes(anchor)
        ? setRange(order, selected, anchor, id, !chosen.has(id))
        : toggleId(order, selected, id)
    anchorRef.current = id
    setSelectedIds(next)
    setHighlightedId(id)
    focusGrid()
  }

  const toggleAll = () => {
    anchorRef.current = null
    setSelectedIds(state === "all" ? [] : [...order])
    focusGrid()
  }

  const highlightByKey = (id: string | null) => {
    if (id === null) return
    setHighlightedId(id)
    if (document.activeElement !== gridRef.current) focusGrid()
  }

  const inScope = (event: KeyboardEvent) => {
    const target = event.target
    if (target === document.body || target === document.documentElement)
      return true
    return target instanceof Node && rootRef.current?.contains(target) === true
  }
  const onTable = (event: KeyboardEvent) => {
    const target = event.target
    return (
      target === document.body ||
      target === document.documentElement ||
      target === gridRef.current
    )
  }

  const navigate = (event: KeyboardEvent, direction: "next" | "previous") => {
    if (!inScope(event) || event.defaultPrevented) return
    event.preventDefault()
    highlightByKey(nextHighlight(order, highlightedId, direction))
  }
  useHotkeys("j,down", (event) => navigate(event, "next"), { enabled: keysOn })
  useHotkeys("k,up", (event) => navigate(event, "previous"), {
    enabled: keysOn,
  })

  useHotkeys(
    "x",
    (event) => {
      if (!inScope(event) || highlightedId === null || !highlightedItem) return
      event.preventDefault()
      toggleRow(highlightedId, false)
    },
    { enabled: keysOn }
  )

  useHotkeys(
    "enter",
    (event) => {
      if (!onOpen || !highlightedItem || !onTable(event)) return
      event.preventDefault()
      onOpen(highlightedItem)
    },
    { enabled: keysOn }
  )

  useHotkeys(
    "esc",
    (event) => {
      if (!inScope(event) || event.defaultPrevented) return
      if (selected.length > 0) {
        event.preventDefault()
        anchorRef.current = null
        setSelectedIds([])
      } else if (highlightedId !== null) {
        event.preventDefault()
        setHighlightedId(null)
      }
    },
    { enabled: ready }
  )

  const reconcile = useEffectEvent(() => {
    if (!ready) return
    if (selected.length !== selectedIds.length) setSelectedIds(selected)
    if (anchorRef.current !== null && !order.includes(anchorRef.current))
      anchorRef.current = null
    if (highlightedId !== null && !order.includes(highlightedId)) {
      setHighlightedId(
        neighbourAfterRemoval(previousOrder.current, order, highlightedId)
      )
    }
    previousOrder.current = order
  })
  useEffect(() => reconcile(), [order, selectedIds, highlightedId, ready])

  useEffect(() => {
    if (highlightedId === null) return
    document
      .getElementById(`${uid}-row-${encodeURIComponent(highlightedId)}`)
      ?.scrollIntoView({ block: "nearest" })
  }, [highlightedId, uid])

  const clickedControl = (event: ReactMouseEvent<HTMLElement>) => {
    const target = event.target as Element
    if (!event.currentTarget.contains(target)) return true
    const control = target.closest(INTERACTIVE)
    return control !== null && control !== event.currentTarget
  }

  const onRowClick = (event: ReactMouseEvent<HTMLElement>, item: T) => {
    if (clickedControl(event)) return
    setHighlightedId(item.id)
    focusGrid()
  }

  const onRowDoubleClick = (event: ReactMouseEvent<HTMLElement>, item: T) => {
    if (clickedControl(event)) return
    setHighlightedId(item.id)
    onOpen?.(item)
  }

  const headerChecked =
    state === "all" ? true : state === "some" ? "mixed" : false

  let body
  if (status === "error") {
    body = (
      <ErrorState
        error={error ?? new Error("Unknown error")}
        onRetry={onRetry}
      />
    )
  } else if (ready && items.length === 0) {
    body = (
      <EmptyState
        title={emptyTitle}
        description={emptyDescription}
        action={
          emptyAction ? (
            <Button variant="outline" size="sm" onClick={emptyAction.onClick}>
              {emptyAction.label}
            </Button>
          ) : undefined
        }
      />
    )
  } else {
    const countLabel = `${selected.length} ${selected.length === 1 ? selectionNoun : `${selectionNoun}s`} selected`
    body = (
      <>
        <div className="flex min-h-0 flex-1 overflow-x-auto">
          <div
            ref={gridRef}
            role="grid"
            tabIndex={0}
            aria-label={ariaLabel}
            aria-multiselectable
            aria-busy={status === "loading"}
            aria-rowcount={items.length + 1}
            aria-colcount={columns.length + 1}
            aria-activedescendant={
              highlightedItem ? rowDomId(highlightedItem.id) : undefined
            }
            className="flex min-w-0 flex-1 flex-col outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-inset"
            style={{ minWidth }}
          >
            <div role="rowgroup" className="shrink-0 border-b bg-muted/40">
              {showBar ? (
                <div role="row" aria-rowindex={1}>
                  <div role="gridcell" aria-colspan={columns.length + 1}>
                    <ActionBar
                      actions={actions}
                      selectedIds={selected}
                      selectionState={state}
                      noun={selectionNoun}
                      onToggleAll={toggleAll}
                    />
                  </div>
                </div>
              ) : (
                <div
                  role="row"
                  aria-rowindex={1}
                  data-mini="header"
                  className="grid h-10 items-center text-xs font-medium text-muted-foreground"
                  style={{ gridTemplateColumns: template }}
                >
                  <div role="columnheader" className="flex justify-center">
                    <IndeterminateCheckbox
                      checked={headerChecked}
                      onToggle={toggleAll}
                      label="Select all rows"
                      disabled={!ready}
                    />
                  </div>
                  {columns.map((column) => (
                    <div
                      key={column.id}
                      role="columnheader"
                      className={cn(
                        "min-w-0 truncate px-3",
                        column.align === "end" && "text-right"
                      )}
                    >
                      {column.header}
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div role="rowgroup" className="min-h-0 flex-1 overflow-y-auto">
              {ready ? (
                items.map((item, index) => {
                  const isSelected = chosen.has(item.id)
                  const isHighlighted = item.id === highlightedId
                  return (
                    <div
                      key={item.id}
                      id={rowDomId(item.id)}
                      role="row"
                      aria-rowindex={index + 2}
                      aria-selected={isSelected}
                      data-mini="row"
                      onClick={(event) => onRowClick(event, item)}
                      onDoubleClick={(event) => onRowDoubleClick(event, item)}
                      className={cn(
                        "grid cursor-default items-center border-b border-border/60 select-none",
                        isSelected
                          ? "bg-[var(--mini-accent-soft)]"
                          : isHighlighted
                            ? "bg-accent"
                            : "hover:bg-accent/50",
                        isHighlighted &&
                          "shadow-[inset_2px_0_0_0_var(--primary)]"
                      )}
                      style={{
                        gridTemplateColumns: template,
                        height: rowHeight,
                      }}
                    >
                      <div role="gridcell" className="flex justify-center">
                        <IndeterminateCheckbox
                          checked={isSelected}
                          tabIndex={-1}
                          onToggle={({ shiftKey }) =>
                            toggleRow(item.id, shiftKey)
                          }
                          label={`Select ${rowLabel ? rowLabel(item) : item.id}`}
                        />
                      </div>
                      {columns.map((column) => (
                        <div
                          key={column.id}
                          role="gridcell"
                          data-mini="cell"
                          className={cn(
                            "flex min-w-0 flex-col justify-center px-3",
                            column.align === "end" &&
                              "items-end text-right tabular-nums"
                          )}
                        >
                          {column.cell(item)}
                        </div>
                      ))}
                    </div>
                  )
                })
              ) : (
                <>
                  <div className="sr-only">
                    <LoadingState label="Loading rows" />
                  </div>
                  {Array.from({ length: PLACEHOLDER_ROWS }, (_, index) => (
                    <div
                      key={index}
                      aria-hidden
                      data-mini="placeholder-row"
                      className="grid items-center border-b border-border/60"
                      style={{
                        gridTemplateColumns: template,
                        height: rowHeight,
                      }}
                    >
                      <div />
                      {columns.map((column, columnIndex) => (
                        <div key={column.id} className="px-3">
                          {columnIndex === 0 ? (
                            <Skeleton
                              className="w-[90%]"
                              style={{ height: Math.max(12, rowHeight - 28) }}
                            />
                          ) : (
                            <Skeleton className="h-5 w-3/4 max-w-20" />
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </>
              )}
            </div>
          </div>
        </div>
        <div aria-live="polite" className="sr-only">
          {showBar ? countLabel : ""}
        </div>
      </>
    )
  }

  return (
    <div
      ref={rootRef}
      className="@container flex h-full min-h-0 flex-col bg-background text-sm"
    >
      {body}
    </div>
  )
}

import { useMemo, useState } from "react"
import {
  ArchiveIcon,
  CheckCheckIcon,
  LockIcon,
  LockOpenIcon,
  MailIcon,
  MergeIcon,
  PaperclipIcon,
  TrashIcon,
} from "lucide-react"
import { toast } from "sonner"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { useCollection } from "@/lib/mini/store"
import { cn } from "@/lib/utils"

import { AssigneeCell } from "./assignee-cell"
import { BulkSelect } from "./bulk-select"
import {
  ASSIGNEES,
  MAILBOXES,
  buildRecordings,
  buildThreads,
  formatAge,
  formatAgo,
  formatLength,
  type Mailbox,
  type Recording,
  type Thread,
} from "./demo-data"
import { TrendCell } from "./trend-cell"
import { formatCount } from "./trend"
import type { BulkSelectAction, BulkSelectColumn } from "./types"

type Preview = "live" | "empty" | "loading" | "error"
type Table = "inbox" | "recordings"

const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]
const TABLES: Array<{ id: Table; label: string }> = [
  { id: "inbox", label: "Inbox threads" },
  { id: "recordings", label: "Recordings" },
]
const NEW_WITHIN = 3 * 24 * 3_600_000

const HINTS = [
  "j/k or arrows move the highlight",
  "x selects the highlighted row",
  "Shift-click a checkbox for a range",
  "Enter or double-click opens",
  "Esc clears the selection, then the highlight",
]

function Segments({ filled, total = 10 }: { filled: number; total?: number }) {
  return (
    <div
      role="img"
      aria-label={`Activity ${filled} of ${total}`}
      className="flex gap-0.5"
    >
      {Array.from({ length: total }, (_, index) => (
        <span
          key={index}
          className={cn(
            "h-4 w-1.5 rounded-[2px]",
            index < filled ? "bg-(--chart-1)" : "bg-muted"
          )}
        />
      ))}
    </div>
  )
}

function reportWrite(write: Promise<unknown>) {
  write.catch((cause: unknown) => {
    toast.error("Couldn't save the change", {
      description: cause instanceof Error ? cause.message : String(cause),
    })
  })
}

export default function Demo() {
  const [seed] = useState(() => {
    const at = Date.now()
    return { at, threads: buildThreads(at), recordings: buildRecordings(at) }
  })
  const threads = useCollection<Thread>("bulk-select-demo", seed.threads)
  const recordings = useCollection<Recording>(
    "bulk-select-demo-recordings",
    seed.recordings
  )
  const [now, setNow] = useState(seed.at)

  const [table, setTable] = useState<Table>("inbox")
  const [preview, setPreview] = useState<Preview>("live")
  const [query, setQuery] = useState("")
  const [mailbox, setMailbox] = useState<Mailbox | "All">("All")
  const [selected, setSelected] = useState<string[]>([])
  const [highlighted, setHighlighted] = useState<string | null>(null)

  const inbox = table === "inbox"
  const store = inbox ? threads : recordings
  const filtering =
    preview !== "empty" && (query.trim() !== "" || (inbox && mailbox !== "All"))

  const threadRows = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return threads.items.filter(
      (thread) =>
        thread.status === "open" &&
        (mailbox === "All" || thread.mailbox === mailbox) &&
        (!needle ||
          `${thread.id} ${thread.subject} ${thread.from} ${thread.preview}`
            .toLowerCase()
            .includes(needle))
    )
  }, [threads.items, query, mailbox])

  const recordingRows = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return recordings.items.filter(
      (recording) =>
        !needle ||
        `${recording.id} ${recording.name} ${recording.who}`
          .toLowerCase()
          .includes(needle)
    )
  }, [recordings.items, query])

  const status =
    preview === "loading" || preview === "error" ? preview : store.status
  const hidden = preview === "empty"

  const patchThreads = (ids: string[], patch: Partial<Thread>) =>
    reportWrite(Promise.all(ids.map((id) => threads.update(id, patch))))
  const patchRecordings = (ids: string[], patch: Partial<Recording>) =>
    reportWrite(Promise.all(ids.map((id) => recordings.update(id, patch))))

  const selectedThreads = threads.items.filter((thread) =>
    selected.includes(thread.id)
  )
  const mailboxes = new Set(selectedThreads.map((thread) => thread.mailbox))
  const mergeReason =
    selected.length < 2
      ? "Select at least two threads to merge."
      : mailboxes.size > 1
        ? "Threads from different mailboxes can't be merged."
        : undefined

  const threadActions: BulkSelectAction[] = [
    {
      id: "done",
      label: "Mark done",
      icon: <CheckCheckIcon aria-hidden />,
      onSelect: (ids) => {
        patchThreads(ids, { status: "done" })
        toast(
          `${ids.length} ${ids.length === 1 ? "thread" : "threads"} marked done`
        )
      },
    },
    {
      id: "archive",
      label: "Archive",
      icon: <ArchiveIcon aria-hidden />,
      onSelect: (ids) => {
        patchThreads(ids, { status: "archived" })
        toast(
          `${ids.length} ${ids.length === 1 ? "thread" : "threads"} archived`
        )
      },
    },
    {
      id: "merge",
      label: "Merge",
      icon: <MergeIcon aria-hidden />,
      disabledReason: mergeReason,
      onSelect: (ids) => {
        const [keep, ...rest] = ids
        patchThreads(rest, { status: "archived" })
        toast(`Merged ${ids.length} threads into ${keep}`)
      },
    },
    {
      id: "unread",
      label: "Mark unread",
      icon: <MailIcon aria-hidden />,
      overflow: true,
      onSelect: (ids) => patchThreads(ids, { unread: true }),
    },
    {
      id: "delete",
      label: "Delete",
      icon: <TrashIcon aria-hidden />,
      overflow: true,
      disabledReason: "You do not have permission to delete threads.",
      onSelect: () => undefined,
    },
  ]

  const lockedSelected = recordings.items.some(
    (recording) => selected.includes(recording.id) && recording.locked
  )
  const recordingActions: BulkSelectAction[] = [
    {
      id: "lock",
      label: "Lock",
      icon: <LockIcon aria-hidden />,
      onSelect: (ids) => patchRecordings(ids, { locked: true }),
    },
    {
      id: "unlock",
      label: "Unlock",
      icon: <LockOpenIcon aria-hidden />,
      onSelect: (ids) => patchRecordings(ids, { locked: false }),
    },
    {
      id: "delete",
      label: "Delete",
      icon: <TrashIcon aria-hidden />,
      overflow: true,
      disabledReason: lockedSelected
        ? "Locked recordings can't be deleted. Unlock them first."
        : undefined,
      onSelect: (ids) => {
        reportWrite(Promise.all(ids.map((id) => recordings.remove(id))))
        toast(
          `${ids.length} ${ids.length === 1 ? "recording" : "recordings"} deleted`
        )
      },
    },
  ]

  const threadColumns: BulkSelectColumn<Thread>[] = [
    {
      id: "thread",
      header: "Thread",
      width: "minmax(0, 2.6fr)",
      cell: (thread) => (
        <>
          <div className="flex min-w-0 items-center gap-1.5">
            {thread.unread ? (
              <>
                <span
                  aria-hidden
                  className="size-1.5 shrink-0 rounded-full bg-primary"
                />
                <span className="sr-only">Unread: </span>
              </>
            ) : null}
            <span className="truncate font-semibold" title={thread.subject}>
              {thread.subject}
            </span>
          </div>
          <p className="truncate text-muted-foreground">{thread.preview}</p>
          <div className="flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground">
            <Badge variant="secondary">{thread.mailbox}</Badge>
            <span className="tabular-nums">{thread.id}</span>
            {thread.attachment ? (
              <>
                <PaperclipIcon className="size-3 shrink-0" aria-hidden />
                <span className="sr-only">Has an attachment</span>
              </>
            ) : null}
            <span className="truncate">{thread.from}</span>
          </div>
        </>
      ),
    },
    {
      id: "last",
      header: "Last activity",
      width: "6.5rem",
      cell: (thread) => (
        <span className="text-sm">{formatAgo(now, thread.lastActivity)}</span>
      ),
    },
    {
      id: "age",
      header: "Age",
      width: "4rem",
      cell: (thread) => (
        <span className="text-sm">{formatAge(now, thread.created)}</span>
      ),
    },
    {
      id: "trend",
      header: "Trend (14 days)",
      width: "9.5rem",
      cell: (thread) => (
        <TrendCell
          values={thread.daily}
          label={`Messages per day for ${thread.id}`}
          caption={now - thread.created < NEW_WITHIN ? "New" : "Ongoing"}
        />
      ),
    },
    {
      id: "messages",
      header: "Messages",
      width: "5.5rem",
      align: "end",
      cell: (thread) => (
        <span className="text-sm">{formatCount(thread.messages)}</span>
      ),
    },
    {
      id: "people",
      header: "People",
      width: "5rem",
      align: "end",
      cell: (thread) => (
        <span className="text-sm">{formatCount(thread.people)}</span>
      ),
    },
    {
      id: "assignee",
      header: "Assignee",
      width: "5.5rem",
      cell: (thread) => (
        <AssigneeCell
          value={thread.assignee}
          groups={ASSIGNEES}
          onChange={(assignee) => patchThreads([thread.id], { assignee })}
          label="Assignee"
        />
      ),
    },
  ]

  const recordingColumns: BulkSelectColumn<Recording>[] = [
    {
      id: "recording",
      header: "Recording",
      width: "minmax(0, 2.2fr)",
      cell: (recording) => (
        <>
          <span className="truncate font-semibold" title={recording.name}>
            {recording.name}
          </span>
          <span className="flex min-w-0 items-center gap-1.5 truncate text-xs text-muted-foreground">
            {recording.locked ? (
              <LockIcon className="size-3 shrink-0" aria-label="Locked" />
            ) : null}
            <span className="truncate">
              {recording.who} · {formatAgo(now, recording.startedAt)}
            </span>
          </span>
        </>
      ),
    },
    {
      id: "device",
      header: "Device",
      width: "6rem",
      cell: (recording) => <span className="text-sm">{recording.device}</span>,
    },
    {
      id: "length",
      header: "Length",
      width: "5rem",
      cell: (recording) => (
        <span className="text-sm tabular-nums">
          {formatLength(recording.seconds)}
        </span>
      ),
    },
    {
      id: "bookmarks",
      header: "Bookmarks",
      width: "6rem",
      align: "end",
      cell: (recording) => (
        <span className="text-sm">{recording.bookmarks}</span>
      ),
    },
    {
      id: "activity",
      header: "Activity",
      width: "8rem",
      cell: (recording) => <Segments filled={recording.activity} />,
    },
  ]

  const switchTable = (next: Table) => {
    setTable(next)
    setSelected([])
    setHighlighted(null)
    setQuery("")
    setMailbox("All")
  }

  const clearFilters = () => {
    setQuery("")
    setMailbox("All")
  }

  const restore = () => {
    const at = Date.now()
    setNow(at)
    setPreview("live")
    clearFilters()
    if (inbox) reportWrite(threads.replaceAll(buildThreads(at)))
    else reportWrite(recordings.replaceAll(buildRecordings(at)))
  }

  const common = {
    status,
    error: new Error(
      `Could not read the ${inbox ? "inbox" : "recordings"} (simulated).`
    ),
    onRetry: () => setPreview("live"),
    selectedIds: selected,
    onSelectedIdsChange: setSelected,
    highlightedId: highlighted,
    onHighlightedIdChange: setHighlighted,
    emptyTitle: filtering
      ? `No ${inbox ? "threads" : "recordings"} match your filters`
      : inbox
        ? "Your inbox is empty"
        : "No recordings yet",
    emptyDescription: filtering
      ? "Check the search spelling and the mailbox filter, or clear the filters."
      : "Nothing is waiting here right now.",
    emptyAction: filtering
      ? { label: "Clear filters", onClick: clearFilters }
      : {
          label: inbox ? "Restore sample threads" : "Restore sample recordings",
          onClick: restore,
        },
  }

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground">
            State preview (demo only)
          </span>
          <div role="group" aria-label="State preview" className="flex gap-1">
            {PREVIEWS.map((name) => (
              <Button
                key={name}
                size="xs"
                variant={preview === name ? "default" : "outline"}
                aria-pressed={preview === name}
                onClick={() => setPreview(name)}
                className="capitalize"
              >
                {name}
              </Button>
            ))}
          </div>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-muted-foreground">
            Table (demo only)
          </span>
          <div role="group" aria-label="Table" className="flex gap-1">
            {TABLES.map((option) => (
              <Button
                key={option.id}
                size="xs"
                variant={table === option.id ? "default" : "outline"}
                aria-pressed={table === option.id}
                onClick={() => switchTable(option.id)}
              >
                {option.label}
              </Button>
            ))}
          </div>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <Input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={inbox ? "Search threads" : "Search recordings"}
          aria-label={inbox ? "Search threads" : "Search recordings"}
          className="h-8 max-w-64"
        />
        {inbox ? (
          <div role="group" aria-label="Mailbox" className="flex gap-1">
            {(["All", ...MAILBOXES] as const).map((name) => (
              <Button
                key={name}
                size="xs"
                variant={mailbox === name ? "secondary" : "outline"}
                aria-pressed={mailbox === name}
                onClick={() => setMailbox(name)}
              >
                {name}
              </Button>
            ))}
          </div>
        ) : null}
        <p className="ml-auto text-xs text-muted-foreground">
          Selection handed to the host:{" "}
          {selected.length > 0 ? selected.join(", ") : "none"}
        </p>
      </div>

      <div className="min-h-[24rem] flex-1 overflow-hidden rounded-lg border">
        {inbox ? (
          <BulkSelect
            key="inbox"
            {...common}
            aria-label="Inbox threads"
            items={hidden ? [] : threadRows}
            columns={threadColumns}
            actions={threadActions}
            selectionNoun="thread"
            rowLabel={(thread) => thread.subject}
            onOpen={(thread) =>
              toast(`Open ${thread.id}: the host decides what opening means`)
            }
          />
        ) : (
          <BulkSelect
            key="recordings"
            {...common}
            aria-label="Recordings"
            items={hidden ? [] : recordingRows}
            columns={recordingColumns}
            actions={recordingActions}
            selectionNoun="recording"
            rowHeight={60}
            minWidth="38rem"
            rowLabel={(recording) => recording.name}
            onOpen={(recording) =>
              toast(`Open ${recording.id}: the host decides what opening means`)
            }
          />
        )}
      </div>

      <p className="text-xs text-muted-foreground">{HINTS.join(" · ")}</p>
    </div>
  )
}

import { CheckIcon, MinusIcon } from "lucide-react"

import { cn } from "@/lib/utils"

/**
 * Checkbox with a third "mixed" state, drawn as a dash. It is a button with
 * `role="checkbox"`, so it takes Space and Enter natively. `onToggle` receives
 * the Shift state of the click for range selection.
 */
export function IndeterminateCheckbox({
  checked,
  onToggle,
  label,
  tabIndex,
  disabled,
  className,
}: {
  checked: boolean | "mixed"
  onToggle: (event: { shiftKey: boolean }) => void
  label: string
  tabIndex?: number
  disabled?: boolean
  className?: string
}) {
  const mixed = checked === "mixed"
  const on = checked !== false
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={mixed ? "mixed" : checked}
      aria-label={label}
      tabIndex={tabIndex}
      disabled={disabled}
      data-state={mixed ? "mixed" : checked ? "checked" : "unchecked"}
      onMouseDown={(event) => {
        if (event.shiftKey) event.preventDefault()
      }}
      onClick={(event) => {
        event.stopPropagation()
        onToggle({ shiftKey: event.shiftKey })
      }}
      className={cn(
        "relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-input bg-background transition-colors outline-none after:absolute after:-inset-2.5 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50",
        on && "border-primary bg-primary text-primary-foreground",
        className
      )}
    >
      {mixed ? (
        <MinusIcon className="size-3.5" aria-hidden />
      ) : checked ? (
        <CheckIcon className="size-3.5" aria-hidden />
      ) : null}
    </button>
  )
}

export type SelectionState = "none" | "some" | "all"

/** Whether none, some or all of `rowCount` visible rows are selected. */
export function selectionState(
  selectedCount: number,
  rowCount: number
): SelectionState {
  if (selectedCount <= 0 || rowCount <= 0) return "none"
  return selectedCount >= rowCount ? "all" : "some"
}

/** `selected` reduced to ids present in `order`, deduplicated, in row order. */
export function pruneSelection(order: string[], selected: string[]): string[] {
  const chosen = new Set(selected)
  return order.filter((id) => chosen.has(id))
}

/** Adds `id` to the selection if absent, removes it if present; result is in row order. */
export function toggleId(
  order: string[],
  selected: string[],
  id: string
): string[] {
  const chosen = new Set(selected)
  if (chosen.has(id)) chosen.delete(id)
  else chosen.add(id)
  return order.filter((rowId) => chosen.has(rowId))
}

/**
 * Selects (`on`) or deselects every row from `anchorId` to `targetId`, both
 * included, in either direction. An id missing from `order` leaves the
 * selection as it was.
 */
export function setRange(
  order: string[],
  selected: string[],
  anchorId: string,
  targetId: string,
  on: boolean
): string[] {
  const from = order.indexOf(anchorId)
  const to = order.indexOf(targetId)
  if (from === -1 || to === -1) return pruneSelection(order, selected)
  const chosen = new Set(selected)
  for (const id of order.slice(Math.min(from, to), Math.max(from, to) + 1)) {
    if (on) chosen.add(id)
    else chosen.delete(id)
  }
  return order.filter((id) => chosen.has(id))
}

/** The row after or before `current`, stopping at the ends; with no current row, the first or last. */
export function nextHighlight(
  order: string[],
  current: string | null,
  direction: "next" | "previous"
): string | null {
  if (order.length === 0) return null
  const index = current === null ? -1 : order.indexOf(current)
  if (index === -1)
    return direction === "next" ? order[0] : order[order.length - 1]
  const target = Math.min(
    order.length - 1,
    Math.max(0, index + (direction === "next" ? 1 : -1))
  )
  return order[target]
}

/**
 * Where the highlight goes when `id` leaves the table: the row now sitting at
 * its old position, or the last row, or nothing when the table is empty.
 */
export function neighbourAfterRemoval(
  previousOrder: string[],
  order: string[],
  id: string
): string | null {
  if (order.length === 0) return null
  const at = previousOrder.indexOf(id)
  if (at === -1) return null
  return order[Math.min(at, order.length - 1)]
}

import { formatCount, trendBars } from "./trend"

/**
 * Small bar histogram of `values` in an inline SVG, with a dashed line at the
 * peak, the peak value at the top right and an optional state word under it.
 * `label` names the series for assistive tech; the peak is appended.
 */
export function TrendCell({
  values,
  caption,
  label = "Trend",
}: {
  values: number[]
  caption?: string
  label?: string
}) {
  const { peak, bars } = trendBars(values)
  return (
    <div className="flex w-full flex-col gap-0.5">
      <div className="flex items-start gap-1.5">
        <svg
          viewBox="0 0 100 24"
          preserveAspectRatio="none"
          role="img"
          aria-label={`${label}, peak ${formatCount(peak)}`}
          className="h-6 min-w-0 flex-1 overflow-visible"
        >
          <line
            x1="0"
            x2="100"
            y1="0.5"
            y2="0.5"
            className="stroke-border"
            strokeDasharray="2 2"
            vectorEffect="non-scaling-stroke"
          />
          {bars.map((bar, index) =>
            bar.height > 0 ? (
              <rect
                key={index}
                x={bar.x}
                y={24 - bar.height}
                width={bar.width}
                height={bar.height}
                className="fill-(--chart-1)"
              />
            ) : null
          )}
        </svg>
        <span
          aria-hidden
          className="text-[10px] leading-none text-muted-foreground tabular-nums"
        >
          {formatCount(peak)}
        </span>
      </div>
      {caption ? (
        <span className="text-xs text-muted-foreground">{caption}</span>
      ) : null}
    </div>
  )
}

/** Bars for a histogram drawn in a 100 by 24 viewBox; every non-zero value gets a visible bar. */
export function trendBars(values: number[]): {
  peak: number
  bars: Array<{ x: number; width: number; height: number }>
} {
  const peak = values.reduce((max, value) => Math.max(max, value), 0)
  if (values.length === 0) return { peak, bars: [] }
  const slot = 100 / values.length
  const bars = values.map((value, index) => ({
    x: index * slot + slot * 0.15,
    width: slot * 0.7,
    height: value <= 0 || peak <= 0 ? 0 : Math.max(1, (value / peak) * 24),
  }))
  return { peak, bars }
}

/** Short count for a table cell: 999, 1.1K, 21K, 1.2M. */
export function formatCount(value: number): string {
  const n = Math.max(0, Math.round(value))
  if (n < 1000) return String(n)
  const units: Array<[string, number]> = [
    ["M", 1_000_000],
    ["K", 1000],
  ]
  for (const [suffix, size] of units) {
    if (n < size) continue
    const scaled = n / size
    const rounded =
      scaled < 10 ? Math.round(scaled * 10) / 10 : Math.round(scaled)
    if (suffix === "K" && rounded >= 1000) return "1M"
    return `${rounded}${suffix}`
  }
  return String(n)
}
